<?php
 namespace Pterodactyl\Http\Controllers\Dezerx; use Illuminate\Http\Response; use Pterodactyl\Http\Controllers\Controller; use Symfony\Component\HttpFoundation\BinaryFileResponse; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class DiscordMediaController extends Controller { private const TYPES = ['png' => 'image/png', 'jpg' => 'image/jpeg', 'jpeg' => 'image/jpeg', 'webp' => 'image/webp', 'gif' => 'image/gif']; public function __invoke(string $path): BinaryFileResponse|Response { $extension = strtolower(pathinfo($path, PATHINFO_EXTENSION)); if (!isset(self::TYPES[$extension]) || str_contains($path, '..')) { throw new NotFoundHttpException(); } $root = realpath(public_path()); $file = realpath(public_path($path)); if ($root === false || $file === false || !str_starts_with($file, $root . DIRECTORY_SEPARATOR) || !is_file($file)) { if (preg_match('#^dezerx/og/([a-z0-9]+)/([a-z0-9-]+)\.png$#', $path, $match) === 1) { return app(OgImageController::class)($match[1], $match[2]); } throw new NotFoundHttpException(); } return response()->file($file, [ 'Content-Type' => self::TYPES[$extension], 'Cache-Control' => 'public, max-age=86400', ]); } } 